package app.space.notes.domain;
import org.junit.Test;
import java.util.*;
import static org.junit.Assert.*;
public class WorkspaceTest {
 @Test public void creationNeverDependsOnAnOldGlobalEditorPreference(){assertNull(Workspace.create(1,false).content);assertNotNull(Workspace.create(1,true).content);}
 @Test public void copiesNeverChangeOrReuseTheOriginalIdentity(){Note source=Note.create(1).rich("Original","Keep",Arrays.asList(new Note.Mark("bold",0,4)),2);Note copy=Workspace.copyToDocument(source,3);assertNotEquals(source.id,copy.id);assertNull(source.content);assertNotNull(copy.content);assertEquals("Keep",source.body);assertEquals("Keep",copy.content.blocks.get(0).text.text);assertEquals("bold",copy.content.blocks.get(0).text.marks.get(0).type);assertEquals(2,source.updatedAt);}
 @Test public void typedWorkspacesDoNotFlattenExistingDocuments(){Note note=Workspace.create(1,false),doc=Workspace.create(2,true);assertTrue(Workspace.includes(note,false));assertFalse(Workspace.includes(doc,false));assertTrue(Workspace.includes(doc,true));assertFalse(Workspace.includes(note,true));assertSame(doc.content,DocumentContent.fromLegacy(doc));}

 @Test public void selectedChecklistStaysInNotesAndKeepsSurroundingStyledText(){Note original=Note.create(1).rich("Mixed","Before\none\ntwo\nAfter",Arrays.asList(new Note.Mark("bold",0,6),new Note.Mark("italic",7,10)),2);DocumentContent c=DocumentContent.fromLegacy(original).inNotesWorkspace(true);Note mixed=original.withContent(c.selectionToChecklist(c.blocks.get(0).id,7,14),3);assertTrue(Workspace.includes(mixed,false));assertFalse(Workspace.includes(mixed,true));assertEquals("Before\n",mixed.content.blocks.get(0).text.text);assertEquals("\nAfter",mixed.content.blocks.get(2).text.text);assertEquals(2,mixed.content.blocks.get(1).items.size());assertEquals("italic",mixed.content.blocks.get(1).items.get(0).marks.get(0).type);assertNull(original.content);assertEquals("Before\none\ntwo\nAfter",original.body);}
 @Test public void mixedNotesMarkerSurvivesEditsMovesCopiesAndLines(){Note source=Note.create(1).edit("Mixed","Text",2);DocumentContent c=DocumentContent.fromLegacy(source).inNotesWorkspace(true);c=c.insert(1,DocumentContent.Block.text("second",new RichText("After",Collections.emptyList()))).move("second",0).withWritingLines(true);assertTrue(c.notesWorkspace);assertTrue(c.replace("second",DocumentContent.Block.text("second",new RichText("Kept",Collections.emptyList()))).notesWorkspace);assertTrue(c.remove("second").notesWorkspace);assertTrue(Workspace.includes(NoteOperations.duplicate(source.withContent(c,3),4),false));}
 @Test public void explicitDocCopyClearsNotesMarkerAndKeepsOriginal(){Note mixed=Note.create(1).withContent(new DocumentContent(Collections.emptyList(),false,true),2);Note doc=Workspace.copyToDocument(mixed,3);assertTrue(Workspace.includes(mixed,false));assertTrue(Workspace.includes(doc,true));assertNotEquals(mixed.id,doc.id);}
 @Test public void workspaceMarkerChangesFingerprintWithoutChangingOldContent(){DocumentContent c=new DocumentContent(Collections.emptyList());assertNotEquals(c.fingerprint(),c.inNotesWorkspace(true).fingerprint());assertEquals(c.fingerprint(),c.inNotesWorkspace(true).inNotesWorkspace(false).fingerprint());}
}
